/* CAT Landing page sections */

function Hero() {
  const wrapRef = React.useRef(null);
  const anchorRef = React.useRef(null);
  const [geo, setGeo] = React.useState(null);

  React.useLayoutEffect(() => {
    function measure() {
      const navA = document.querySelector('.btn-nav-a');
      const navB = document.querySelector('.btn-nav-b');
      const anchorEl = anchorRef.current;
      const wrapEl = wrapRef.current;
      if (!navA || !navB || !anchorEl || !wrapEl) { setGeo(null); return; }
      const wrapRect = wrapEl.getBoundingClientRect();
      const ox = wrapRect.left, oy = wrapRect.top;
      const anchorRect = anchorEl.getBoundingClientRect();
      if (window.scrollY > 24 || wrapRect.bottom < 0) { setGeo(null); return; }
      const aRect = navA.getBoundingClientRect();
      const bRect = navB.getBoundingClientRect();
      const anchor = { x: anchorRect.left - ox + anchorRect.width / 2, y: anchorRect.top - oy };
      const endA = { x: aRect.left - ox + aRect.width / 2, y: aRect.top - oy + aRect.height + 8 };
      const endB = { x: bRect.left - ox + bRect.width / 2, y: bRect.top - oy + bRect.height + 8 };
      const mid = { x: (endA.x + endB.x) / 2, y: (endA.y + endB.y) / 2 };
      const start = { x: anchor.x, y: anchor.y - 6 };
      const fork = { x: start.x + (mid.x - start.x) * 0.62, y: start.y + (mid.y - start.y) * 0.62 };
      function curve(p0, p1, bendSign) {
        const dx = p1.x - p0.x, dy = p1.y - p0.y;
        const len = Math.hypot(dx, dy) || 1;
        const nx = -dy / len, ny = dx / len;
        const bend = Math.min(50, len * 0.2) * bendSign;
        const ctrl = { x: (p0.x + p1.x) / 2 + nx * bend, y: (p0.y + p1.y) / 2 + ny * bend };
        const path = `M ${p0.x} ${p0.y} Q ${ctrl.x} ${ctrl.y} ${p1.x} ${p1.y}`;
        const angle = Math.atan2(p1.y - ctrl.y, p1.x - ctrl.x) * 180 / Math.PI;
        return { path, angle };
      }
      const trunk = curve(start, fork, 1);
      const branchA = curve(fork, endA, -1);
      const branchB = curve(fork, endB, 1);
      setGeo({ trunk, branchA, branchB, endA, endB });
    }
    measure();
    window.addEventListener('resize', measure);
    window.addEventListener('scroll', measure, { passive: true });
    return () => {
      window.removeEventListener('resize', measure);
      window.removeEventListener('scroll', measure);
    };
  }, []);

  return (
    <section className="hero" id="use-it">
      <div className="hero-red-inner" ref={wrapRef}>
        <div className="hero-navy-col">
          <div className="hero-logo-center">
            <img className="hero-logo-img" src="cat-logo-white.png" alt="The CAT" />
            <h1 className="hero-title">
              The <span className="cat-letter">C</span>onstructive <span className="cat-letter">A</span>lignment <span className="cat-letter">T</span>ool
            </h1>
          </div>
          <p className="hero-sub">
            A course design tool for curriculum designers and teaching academics
          </p>
        </div>
        <div className="hero-cta-col">
          <span className="eyebrow use-it-eyebrow">Before you read on</span>
          <h2 className="use-it-title">The best way to <span ref={anchorRef}>learn</span> about the CAT is to use it</h2>
          <p className="use-it-sub">Each pathway has instructions, but you can always return to the guides if you need more information, or want to see some use cases.</p>
        </div>
        {geo && (
          <svg width="1" height="1" style={{ position: 'absolute', top: 0, left: 0, overflow: 'visible', pointerEvents: 'none', zIndex: 60 }}>
            <path d={geo.trunk.path} stroke="#fff" strokeWidth="2" fill="none" strokeLinecap="round" opacity="0.85" />
            <path d={geo.branchA.path} stroke="#fff" strokeWidth="2" fill="none" strokeLinecap="round" opacity="0.85" />
            <path d={geo.branchB.path} stroke="#fff" strokeWidth="2" fill="none" strokeLinecap="round" opacity="0.85" />
            <g style={{ transform: `translate(${geo.endA.x}px, ${geo.endA.y}px) rotate(${geo.branchA.angle}deg)` }}>
              <path d="M-12 -7 L2 0 L-12 7 Z" fill="#fff" stroke="none" />
            </g>
            <g style={{ transform: `translate(${geo.endB.x}px, ${geo.endB.y}px) rotate(${geo.branchB.angle}deg)` }}>
              <path d="M-12 -7 L2 0 L-12 7 Z" fill="#fff" stroke="none" />
            </g>
          </svg>
        )}
      </div>
    </section>);
}

function ProblemBand() {
  return (
    <section className="problem-band">
      <div className="container problem-band-inner">
        <p className="hero-problem">See whether the curriculum you designed is the curriculum students actually experience.</p>
        <p className="hero-lede">
          The CAT is a tool for designing and verifying how your course learning outcomes, assignments, and rubric criteria fit together as a coherent system. It visualises constructive alignment in your course (unit/subject), checking whether the intended and the mapped curriculum match what students <strong><em style={{color:'#5B3DF5'}}>actually</em></strong> experience. It might confirm the design is working. It might reveal a gap worth addressing. Either way, you'll know, rather than assume.
        </p>
        <p className="hero-research-note">
          The CAT is an <a href="#research">educational research project</a>. The tool is free to use; research participation is separate and voluntary.
        </p>
      </div>
    </section>);
}

function OverviewCells() {
  const contexts = [
    { num: '01', tag: 'Verification', title: 'Examine a course already in delivery', body: 'Check whether the CLO emphasis intended is what the assignments actually measure, a useful step before the course next runs.', contextId: 'verifying' },
    { num: '02', tag: 'Refinement', title: 'Test revisions before committing', body: 'See how a proposed change to an assignment, rubric, or CLO propagates through the rest of the course structure before you lock it in.', contextId: 'refining' },
    { num: '03', tag: 'New design', title: 'Build alignment from the start', body: 'Begin from whichever component is clearest, outcomes, assignments, or rubric criteria, and let the derivations scaffold the rest.', contextId: 'designing' },
  ];
  const terms = [
    { term: 'Course', def: 'A single taught unit, sometimes called a subject, paper, module, or unit of study depending on your institution. In this tool, one course = one set of CLOs and one assessment structure.' },
    { term: 'CLO', def: 'Course Learning Outcome. A statement of what a student is expected to demonstrate by the end of the course. Different institutions use LO, ULO, UO, or ILO for the same concept.' },
    { term: 'Assignment', def: 'Any summative assessment task, an essay, exam, project, presentation, portfolio, etc. The CAT treats each graded task as a single assignment with a percentage weight.' },
    { term: 'Rubric', def: 'The marking guide for an assignment. Each criterion in the rubric can be tagged to one or more CLOs. Pathway B uses these tags to calculate the implied CLO emphasis.' },
  ];
  const cells = [
    { key: 'what', num: '01', eyebrow: 'The tool', title: 'What the CAT does' },
    { key: 'when', num: '02', eyebrow: 'Start here', title: 'When to use it' },
    { key: 'why', num: '03', eyebrow: 'The payoff', title: 'Why it matters' },
  ];
  return (
    <section className="explore-band" id="how">
      <div className="container">
        <div className="explore-head">
          <span className="eyebrow explore-eyebrow" style={{fontSize:'22px',color:'#FFFFFF',fontWeight:800,letterSpacing:'0.02em'}}>01 · The best way to learn the CAT is to use it</span>
          <p className="explore-lede"></p>
        </div>
        {cells.map((c) => (
          <div key={c.key} style={{ marginTop: c.key === 'what' ? 0 : 40 }}>
            <div className="explore-tab is-active" style={{ cursor: 'default', marginBottom: 12 }}>
              <span className="explore-num mono">{c.num}</span>
              <span className="explore-trigger-text">
                <span className="explore-trigger-eyebrow mono">{c.eyebrow}</span>
                <span className="explore-trigger-title">{c.title}</span>
              </span>
            </div>
            <div className="explore-window" style={{ animation: 'none' }}>
              <div className="explore-panel-inner">
                {c.key === 'what' &&
                <React.Fragment>
                    <p className="explore-panel-sub">The CAT quantifies the relationship between course learning outcomes (CLOs) and summative assessment via two pathways.</p>
                    <div className="what-summary">
                      <p className="what-summary-text"><strong>Pathway A</strong> starts from your CLO weightings and mapping, and derives the assignment weights and rubric composition they imply. Includes a teaching sequence planner to map readiness across your course.<br /><strong>Pathway B</strong> starts from your assignments and rubrics, and derives the CLO emphasis they actually deliver.</p>
                      <EssenceStage />
                      <div className="what-summary-insights">
                        <PrincipleAccordion title="A CLO's weighting is a claim about how much of the assessment measures it." triggerStyle={{color:'#fff',backgroundColor:'var(--c-red)'}} tagColor="#fff" defaultOpen>
                          <p className="principle-body">If a learning outcome is <strong>40% of a course</strong>, then <strong>40% of the assessed marks</strong> should measure it. CLO weightings and the way they're distributed across assignments are two views of the same emphasis. The CAT makes that relationship explicit, and shows how closely the current design holds to it.</p>
                          <PrincipleWeightingViz />
                        </PrincipleAccordion>
                        <PrincipleAccordion title="Alignment constrains demand; it does not determine it." triggerStyle={{color:'#fff',backgroundColor:'var(--c-red-2)'}} tagColor="#fff" defaultOpen>
                          <p className="principle-body">A course's outcomes each occupy a bounded share of the teaching period, and readiness tracks how much of that share has genuinely been built by any given point. Demand is a separate decision: how much of an outcome's assessment weight a given assignment should claim, expressed as a ratio across all the assignments it is mapped to. The two are related by one rule: <strong>cumulative demand can never exceed cumulative readiness</strong>. An assignment cannot fairly ask more of an outcome than the teaching sequence has, by that point, made available.</p>
                      <p className="principle-body">Within that limit, many demand patterns are equally valid. The two panels below read the same way: the dashed line is cumulative readiness, the proportion of the outcome taught by each assignment (38%, then 72%, then all of it), and the solid line is cumulative demand, the proportion of that outcome's assessment weight claimed so far. Both lines only ever rise, since each assignment adds to what has already been claimed, and both reach 100% by the third assignment, because the whole weight has to have been taught by the final assignment. They get there differently. In Pattern A, the first assignment assesses just 5% of the outcome; the teaching between A1 and A2 adds another 20%, so 25% of the outcome has been assessed by that point; the weeks between A2 and A3 cover the remainder, so the final assignment can draw on all of it and takes the remaining 75%. Pattern B spreads the same weight more evenly: 35%, then a further 35%, then the last 30%. Neither line ever rises above the dashed one. The mapping does not just record a connection; it is a decision about where an outcome's assessment weight sits, made visible as a number in a table, and readiness is the ceiling that decision has to stay under, not the curve it must trace.</p>
                      <div className="mapping-sequence-visual"><ReadinessCeilingViz /></div>
                    </PrincipleAccordion>
                      </div>
                    </div>
                  </React.Fragment>}
                {c.key === 'when' &&
                <React.Fragment>
                    <p className="explore-panel-sub">Which of these matches where the course sits right now?</p>
                    <div className="explore-contexts">
                      {contexts.map((ctx, ci) => (
                        <a className="uci-card explore-uci" href={`scenarios.html#${ctx.contextId}`} key={ci}>
                          <span className="mono uci-num">{ctx.num}</span>
                          <div className="uci-tag mono">{ctx.tag}</div>
                          <h3 className="uci-title">{ctx.title}</h3>
                          <p className="uci-body">{ctx.body}</p>
                          <span className="uci-link mono">See real scenarios
                            <svg width="12" height="12" viewBox="0 0 14 14" fill="none"><path d="M3 7h8m0 0L7.5 3.5M11 7l-3.5 3.5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" /></svg>
                          </span>
                        </a>
                      ))}
                    </div>
                    <div className="explore-terms" style={{backgroundColor:'var(--c-bg-2)'}}>
                      <span className="explore-terms-label mono">Key terms used in this tool</span>
                      <div className="explore-terms-grid">
                        {terms.map((t, ti) => (
                          <div className="explore-term" key={ti}>
                            <span className="explore-term-name mono">{t.term}</span>
                            <span className="explore-term-def">{t.def}</span>
                          </div>
                        ))}
                      </div>
                    </div>
                  </React.Fragment>}
                {c.key === 'why' &&
                <React.Fragment>
                    <p className="explore-panel-sub" style={{color:'#8E84E4',fontWeight:700}}>What clarity at the start leads to, for the educator and the student.</p>
                    <BenefitsWrap />
                  </React.Fragment>}
              </div>
            </div>
          </div>
        ))}
      </div>
    </section>);
}

// ─── Theme visuals ───

function ClarityViz() {
  const intended = [{ n: 'Assignment 1', v: 30 }, { n: 'Assignment 2', v: 40 }, { n: 'Assignment 3', v: 30 }];
  const actual = [{ n: 'Assignment 1', v: 28 }, { n: 'Assignment 2', v: 47 }, { n: 'Assignment 3', v: 25 }];
  const colors = ['#140F50', '#5B3DF5', '#836BFF'];
  const boundary = (data) => data[0].v + data[1].v;
  const Row = ({ label, sub, data, showDrift }) => (
    <div className="clarity-row">
      <div className="clarity-row-label">{label}<span>{sub}</span></div>
      <div className="clarity-bar-wrap">
        <div className="clarity-bar">
          {data.map((d, i) => (
            <div key={i} className="clarity-seg" style={{ width: d.v + '%', background: colors[i] }}>
              {d.v} hrs
              <span className="clarity-seg-name">{d.n}</span>
            </div>
          ))}
        </div>
        <div className="clarity-bar-divider" style={{ left: boundary(data) + '%' }} />
        {showDrift && <span className="clarity-drift-tag" style={{ left: `calc(${boundary(data)}% - 8px)` }}>+7 hrs drift</span>}
      </div>
    </div>
  );
  return (
    <div className="clarity-viz">
      <span className="mono clarity-tag">Illustrative example · Verification</span>
      <Row label="Intended" sub="(100 hrs)" data={intended} />
      <Row label="Actual" sub="(100 hrs)" data={actual} showDrift />
      <p className="clarity-caption">The teaching academic intended the distribution to be as the top row, and importantly, resourced the course to run in that way. However, what the mapping revealed is that seven hours drifted into the middle task. The educator thought students had more time for the last task than what they actually had. This began to explain why students had not achieved as well as the educator thought they should have in their final assignment.</p>
    </div>
  );
}

