function ReadinessCeilingViz() {
  const W = 340, H = 196, L = 40, R = 14, T = 16, B = 30;
  const xs = [0, 1, 2].map(i => L + i * ((W - L - R) / 2));
  const y = v => T + (1 - v / 100) * (H - T - B);
  const readiness = [38, 72, 100];
  const line = vals => vals.map((v, i) => `${i ? 'L' : 'M'} ${xs[i]} ${y(v)}`).join(' ');
  const zone = `${line(readiness)} L ${xs[2]} ${T} L ${xs[0]} ${T} Z`;
  const panels = [
    { tag: 'Pattern A', cap: 'Held back, then assessed heavily late', demand: [5, 25, 100], inc: '5 + 20 + 75' },
    { tag: 'Pattern B', cap: 'Front-loaded, then receding', demand: [35, 70, 100], inc: '35 + 35 + 30' },
  ];
  return (
    <div className="rc-viz">
      <div className="rc-legend">
        <span className="rc-legend-item"><span className="rc-legend-swatch is-dashed"></span>Cumulative readiness: how much of the outcome has been taught (38 / 72 / 100%)</span>
        <span className="rc-legend-item"><span className="rc-legend-swatch is-demand"></span>Cumulative demand: how much of the outcome's assessment weight has been claimed</span>
        <span className="rc-legend-item"><span className="rc-legend-swatch is-zone"></span>Not permitted</span>
      </div>
      <div className="rc-panels">
        {panels.map((p, pi) => (
          <div className="rc-panel" key={pi}>
            <span className="rc-tag">{p.tag}</span>
            <p className="rc-cap">{p.cap}</p>
            <p className="rc-axis-title">Vertical axis: % of the outcome, cumulative. Horizontal: the three assignments it is mapped to.</p>
            <svg viewBox={`0 0 ${W} ${H}`} role="img" aria-label={`${p.tag}: cumulative demand of ${p.demand.join('%, ')}% across three assignments, staying beneath a readiness ceiling of ${readiness.join('%, ')}%`}>
              <path d={zone} fill="rgba(20,15,80,0.07)" />
              {[0, 50, 100].map(v => (
                <g key={v}>
                  <line x1={L} y1={y(v)} x2={W - R} y2={y(v)} stroke="#140F50" strokeWidth="0.6" opacity={v === 0 ? 0.3 : 0.1} />
                  <text x={L - 8} y={y(v) + 3.5} textAnchor="end" fontSize="9" fill="#6B6790">{v}%</text>
                </g>
              ))}
              {xs.map((x, i) => (
                <text key={i} x={x} y={H - 11} textAnchor="middle" fontSize="9.5" fill="#6B6790">{`A${i + 1}`}</text>
              ))}
              <path d={line(readiness)} fill="none" stroke="#140F50" strokeWidth="1.8" strokeDasharray="5 4" opacity="0.6" strokeLinecap="round" />
              {readiness.map((v, i) => <circle key={i} cx={xs[i]} cy={y(v)} r="2.6" fill="#fff" stroke="#140F50" strokeWidth="1.4" opacity="0.7" />)}
              <path d={line(p.demand)} fill="none" stroke="#D31569" strokeWidth="2.2" strokeLinecap="round" />
              {p.demand.map((v, i) => (
                <g key={i}>
                  <circle cx={xs[i]} cy={y(v)} r="3.4" fill="#D31569" />
                  <text x={xs[i]} y={v < 20 ? y(v) - 8 : y(v) + 16} textAnchor={i === 0 ? 'start' : 'middle'} fontSize="9.5" fill="#D31569" fontWeight="600">{v + '%'}</text>
                </g>
              ))}
            </svg>
            <span className="rc-note"><span className="rc-note-dot"></span><span>{`Assignment by assignment: ${p.inc}% · readiness ceiling never crossed`}</span></span>
          </div>
        ))}
      </div>
      <p className="rc-caption">Two different, equally valid demand patterns for the same outcome, both staying beneath the same readiness ceiling.</p>
    </div>
  );
}

